import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // Set once a user completes a magic-link sign-in with this address.
  emailVerified: string | null;
  // Absent for users who have never set a password (Google-only or magic-link-only users).
  passwordHash?: string;
  // Bumped to "now" (unix seconds) by "sign out of all devices". Any JWT issued
  // before this timestamp is rejected the next time it's used — see the `jwt`
  // callback in src/auth.ts.
  sessionsValidFrom: number;
};

// One row per (provider, providerAccountId) a user has signed in with — Google
// OAuth and magic-link email both go through this so the same email always
// resolves to the same account.
type Account = {
  userId: string;
  provider: string;
  providerAccountId: string;
};

// Magic-link one-time tokens, consumed on first use. Auth.js hashes the token
// before it ever reaches this store.
type VerificationToken = {
  identifier: string;
  token: string;
  expires: string; // ISO
};

// Next.js (Turbopack, in both dev and prod) can load this module more than once —
// route handlers and page renders don't always land in the same module instance.
// Pin the stores on globalThis so every instance reads/writes the same data within
// this process; otherwise sign-ups made via /api/signup silently "vanish" when the
// dashboard re-reads users through a different copy of this module.
const globalForUsers = globalThis as unknown as {
  __notelyUsers?: User[];
  __notelyAccounts?: Account[];
  __notelyVerificationTokens?: VerificationToken[];
};

const users: User[] =
  globalForUsers.__notelyUsers ??
  (globalForUsers.__notelyUsers = [
    {
      id: "1",
      email: "ada@example.com",
      name: "Ada",
      createdAt: "2026-01-04",
      emailVerified: null,
      sessionsValidFrom: 0,
    },
    {
      id: "2",
      email: "grace@example.com",
      name: "Grace",
      createdAt: "2026-02-11",
      emailVerified: null,
      sessionsValidFrom: 0,
    },
  ]);

const accounts: Account[] = globalForUsers.__notelyAccounts ?? (globalForUsers.__notelyAccounts = []);

const verificationTokens: VerificationToken[] =
  globalForUsers.__notelyVerificationTokens ?? (globalForUsers.__notelyVerificationTokens = []);

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const normalized = email.toLowerCase();
  return users.find((u) => u.email.toLowerCase() === normalized);
}

function nextId(): string {
  const max = users.reduce((acc, u) => Math.max(acc, Number(u.id) || 0), 0);
  return String(max + 1);
}

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

function nowSeconds(): number {
  return Math.floor(Date.now() / 1000);
}

// Used by the credentials sign-up flow.
export async function createUser({
  email,
  name,
  password,
}: {
  email: string;
  name: string;
  password: string;
}): Promise<User> {
  if (await getUserByEmail(email)) {
    throw new Error("A user with that email already exists");
  }
  const passwordHash = await bcrypt.hash(password, 10);
  const user: User = {
    id: nextId(),
    email,
    name,
    createdAt: today(),
    emailVerified: null,
    sessionsValidFrom: 0,
    passwordHash,
  };
  users.push(user);
  return user;
}

// Used by the credentials sign-in flow. Returns the user only if the password matches.
export async function verifyPassword(
  email: string,
  password: string
