import type { Adapter, AdapterUser } from "next-auth/adapters";
import {
  createUserRecord,
  createVerificationToken,
  getUser,
  getUserByAccount,
  getUserByEmail,
  linkAccount,
  updateUserRecord,
  useVerificationToken,
  type User,
} from "@/lib/users";

// Adapts our in-memory user store (src/lib/users.ts) to the Auth.js Adapter
// interface. This is only needed for two things:
//  - Google OAuth and magic-link email both need somewhere to resolve
//    "this provider account" -> "this local user" and provision one on first use.
//  - The Email (magic-link) provider needs somewhere to store one-time
//    verification tokens.
// Sessions are NOT handled here — the app uses JWT sessions (see src/auth.ts),
// so Auth.js never calls the session-related adapter methods.
function toAdapterUser(user: User): AdapterUser {
  return {
    id: user.id,
    email: user.email,
    name: user.name,
    emailVerified: user.emailVerified ? new Date(user.emailVerified) : null,
  };
}

export const authAdapter: Adapter = {
  async createUser(user) {
    const created = await createUserRecord({
      email: user.email,
      name: user.name,
      emailVerified: user.emailVerified,
    });
    return toAdapterUser(created);
  },

  async getUser(id) {
    const user = await getUser(id);
    return user ? toAdapterUser(user) : null;
  },

  async getUserByEmail(email) {
    const user = await getUserByEmail(email);
    return user ? toAdapterUser(user) : null;
  },

  async getUserByAccount({ provider, providerAccountId }) {
    const user = await getUserByAccount({ provider, providerAccountId });
    return user ? toAdapterUser(user) : null;
  },

  async updateUser(user) {
    const updated = await updateUserRecord(user.id, {
      name: user.name,
      email: user.email,
      emailVerified: user.emailVerified,
    });
    return toAdapterUser(updated);
  },

  async linkAccount(account) {
    await linkAccount({
      userId: account.userId,
      provider: account.provider,
      providerAccountId: account.providerAccountId,
    });
  },

  async createVerificationToken(token) {
    await createVerificationToken(token);
    return token;
  },

  async useVerificationToken(params) {
    const token = await useVerificationToken(params);
    return token ?? null;
  },
};

