  // resolve "this provider account" to a local user (and a place for the Email
  // provider to store its one-time tokens). Sessions stay JWT-based — see the
  // `session: { strategy: "jwt" }` below and the comment on the `jwt` callback —
  // so the Credentials provider (which Auth.js only supports with JWT sessions)
  // keeps working unchanged.
  adapter: authAdapter,
  providers: [
    Google({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
      // Preserves this app's original behavior: a Google sign-in with the same
      // email as an existing credentials account links straight to it instead
      // of erroring out. Safe here because we treat email as the account key
      // throughout; a stricter app should require an explicit "link account"
      // step instead.
      allowDangerousEmailAccountLinking: true,
    }),
    Credentials({
      name: "Email and password",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      authorize: async (credentials) => {
        const email = credentials?.email;
        const password = credentials?.password;
        if (typeof email !== "string" || typeof password !== "string") return null;

        const user = await verifyPassword(email, password);
        if (!user) return null;

        return { id: user.id, email: user.email, name: user.name };
      },
    }),
    Resend({
      apiKey: process.env.AUTH_RESEND_KEY,
      from: process.env.AUTH_EMAIL_FROM ?? "Notely <no-reply@notely.dev>",
    }),
  ],
  session: { strategy: "jwt" },
  pages: {
    signIn: "/signin",
  },
  callbacks: {
    async jwt({ token, user }) {
      // On initial sign-in `user` is the id Auth.js just resolved (via a
      // provider's `authorize`, or via the adapter for Google/magic-link).
      if (user?.id) token.sub = user.id;
      if (!token.sub) return token;

      // Re-checked on every request: if the account was deleted, or "sign out
      // of all devices" was used after this JWT was issued, drop the session.
      // Returning null here is what Auth.js treats as "invalidate this token" —
      // it clears the session cookie on the next request.
      const dbUser = await getUser(token.sub);
      if (!dbUser) return null;
      if (dbUser.sessionsValidFrom > (token.iat ?? 0)) return null;

      token.name = dbUser.name;
      token.email = dbUser.email;
      return token;
    },
    async session({ session, token }) {
      if (token.sub) session.user.id = token.sub;
      return session;
    },
  },
});

