"use server";

import { redirect } from "next/navigation";
import { auth, signOut } from "@/auth";
import { changePassword, deleteUserById, getCurrentUser, invalidateAllSessions } from "@/lib/users";

export type ActionState = { error?: string; success?: string };

async function requireUserId(): Promise<string> {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Not signed in");
  return session.user.id;
}

export async function changePasswordAction(
  _prev: ActionState,
  formData: FormData
): Promise<ActionState> {
  const userId = await requireUserId();
  const currentPassword = String(formData.get("currentPassword") ?? "");
  const newPassword = String(formData.get("newPassword") ?? "");
  const confirmPassword = String(formData.get("confirmPassword") ?? "");

  if (newPassword.length < 8) {
    return { error: "New password must be at least 8 characters." };
  }
  if (newPassword !== confirmPassword) {
    return { error: "New passwords don't match." };
  }

  const user = await getCurrentUser();
  try {
    await changePassword(userId, {
      currentPassword: user?.passwordHash ? currentPassword : undefined,
      newPassword,
    });
  } catch (err) {
    return { error: err instanceof Error ? err.message : "Couldn't update password." };
  }

  return { success: user?.passwordHash ? "Password updated." : "Password set." };
}

export async function signOutAllDevicesAction(): Promise<void> {
  const userId = await requireUserId();
  await invalidateAllSessions(userId);
  // This also invalidates the current session (by design — see users.ts), so
  // send the browser through the normal sign-out flow to clear its cookie too.
  await signOut({ redirectTo: "/signin" });
}

export async function deleteAccountAction(): Promise<void> {
  const userId = await requireUserId();
  await deleteUserById(userId);
  await signOut({ redirectTo: "/" });
}

// Only used to redirect unauthenticated visitors away from /account without
// depending on the proxy/middleware matcher.
export async function ensureSignedIn() {
  const session = await auth();
  if (!session?.user) redirect("/signin?callbackUrl=/account");
  return session;
}

