npx tsx -e '
import { createUser, verifyPassword, changePassword, invalidateAllSessions, deleteUserById, getUser, getUserByEmail } from "./src/lib/users.ts";

async function main() {
  const u = await createUser({ email: "unit@example.com", name: "Unit", password: "password123" });
  console.log("created", u.id, u.sessionsValidFrom);

  const before = u.sessionsValidFrom;
  await invalidateAllSessions(u.id);
  const after = (await getUser(u.id)).sessionsValidFrom;
  console.log("invalidate bumped:", after > before, { before, after });

  // wrong current password should fail
  try {
    await changePassword(u.id, { currentPassword: "wrong", newPassword: "newpassword123" });
    console.log("BUG: wrong current password accepted");
  } catch (e) {
    console.log("correctly rejected wrong current password:", e.message);
  }

  await changePassword(u.id, { currentPassword: "password123", newPassword: "newpassword123" });
  const verified = await verifyPassword("unit@example.com", "newpassword123");
  console.log("new password verifies:", !!verified);

  await deleteUserById(u.id);
  console.log("deleted, lookup now:", await getUserByEmail("unit@example.com"));
}

main();
'
